func CanAdminister(r store.Role) bool { return r == store.RoleOwner || r == store.RoleAdmin }

// CanManageTeam reports whether a role may manage the organization's settings, members and invites.
func CanManageTeam(r store.Role) bool { return CanAdminister(r) }

// IsOwner reports whether a role is owner. Only owners may give or take away the owner and admin roles.
func IsOwner(r store.Role) bool { return r == store.RoleOwner }

