// SetMemberRole changes a member's role.
func (s *Store) SetMemberRole(orgID, userID string, role Role) (Member, error) {
	if !role.Valid() {
		return Member{}, invalid("unknown role %q", role)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	m, ok := s.members[k]
	if !ok {
		return Member{}, ErrNotFound
	}
	m.Role = role
	s.members[k] = m
	return m, nil
}

// RemoveMember removes a user from an organization. Their API keys for it stop working, as they are no longer a member.
func (s *Store) RemoveMember(orgID, userID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	if _, ok := s.members[k]; !ok {
		return ErrNotFound
	}
	delete(s.members, k)
	return nil
}

args.new_string:
// SetMemberRole changes a member's role. It fails with ErrLastOwner when the member is the organization's only owner and
// the new role is not owner.
func (s *Store) SetMemberRole(orgID, userID string, role Role) (Member, error) {
	if !role.Valid() {
		return Member{}, invalid("unknown role %q", role)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	m, ok := s.members[k]
	if !ok {
		return Member{}, ErrNotFound
	}
	if m.Role == RoleOwner && role != RoleOwner && s.ownerCount(orgID) == 1 {
		return Member{}, ErrLastOwner
	}
	m.Role = role
	s.members[k] = m
	return m, nil
}

// RemoveMember removes a user from an organization. Their API keys for it stop working, as they are no longer a member.
// It fails with ErrLastOwner when the user is the organization's only owner.
func (s *Store) RemoveMember(orgID, userID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	m, ok := s.members[k]
	if !ok {
		return ErrNotFound
	}
	if m.Role == RoleOwner && s.ownerCount(orgID) == 1 {
		return ErrLastOwner
	}
	delete(s.members, k)
	return nil
}

// ownerCount counts an organization's owners. The caller holds s.mu.
func (s *Store) ownerCount(orgID string) int {
	n := 0
	for _, m := range s.members {
		if m.OrgID == orgID && m.Role == RoleOwner {
			n++
		}
	}
	return n
}

