func privileged(r store.Role) bool { return r == store.RoleOwner || r == store.RoleAdmin }

func (s *Server) updateMember(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	target := r.PathValue("user_id")
	if target == p.UserID {
		writeError(w, http.StatusForbidden, "forbidden", "nobody may change their own role")
		return
	}
	var in struct {
		Role store.Role `json:"role"`
	}
	if !decode(w, r, &in) {
		return
	}
	cur, ok := s.store.Member(p.OrgID, target)
	if !ok {
		s.storeError(w, store.ErrNotFound)
		return
	}
	if (privileged(cur.Role) || privileged(in.Role)) && !auth.IsOwner(p.Role) {
		writeError(w, http.StatusForbidden, "forbidden", "only owners change the owner and admin roles")
		return
	}
	m, err := s.store.SetMemberRole(p.OrgID, target, in.Role)
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, s.memberView(m))
}

