// privileged reports whether a role is one only owners may give, take away or change: owner and admin.
func privileged(r store.Role) bool { return r == store.RoleOwner || r == store.RoleAdmin }

func (s *Server) updateMember(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	target := r.PathValue("user_id")
	if target == p.UserID {
		writeError(w, http.StatusForbidden, "forbidden", "nobody may change their own role")
		return
	}
	var in struct {
		Role store.Role `json:"role"`
	}
	if !decode(w, r, &in) {
		return
	}
	cur, ok := s.store.Member(p.OrgID, target)
	if !ok {
		s.storeError(w, store.ErrNotFound)
		return
	}
	if (privileged(cur.Role) || privileged(in.Role)) && !auth.IsOwner(p.Role) {
		writeError(w, http.StatusForbidden, "forbidden", "only owners change the owner and admin roles")
		return
	}
	m, err := s.store.SetMemberRole(p.OrgID, target, in.Role)
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, s.memberView(m))
}

// removeMember removes a member. Anyone may leave: a member may always remove themselves.
func (s *Server) removeMember(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	target := r.PathValue("user_id")
	if target != p.UserID {
		if !auth.CanManageTeam(p.Role) {
			writeError(w, http.StatusForbidden, "forbidden", "only owners and admins remove other members")
			return
		}
		cur, ok := s.store.Member(p.OrgID, target)
		if !ok {
			s.storeError(w, store.ErrNotFound)
			return
		}
		if privileged(cur.Role) && !auth.IsOwner(p.Role) {
			writeError(w, http.StatusForbidden, "forbidden", "only owners remove owners and admins")
			return
		}
	}
	if err := s.store.RemoveMember(p.OrgID, target); err != nil {
		s.storeError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

