// TestRoleMatrix checks every endpoint's role table: a role that may not call an endpoint gets 403 "forbidden", and one
// that may gets past the role check (any answer but 401 or 403).
func TestRoleMatrix(t *testing.T) {
	e := apitest.New(t)
	keys := map[store.Role]string{store.RoleOwner: e.Acme.Key}
	for _, role := range allRoles[1:] {
		_, keys[role] = e.AddMember(e.Acme, string(role)+"@acme.example", role)
	}
	matrix := []struct {
		method, path string
		body         any
		allowed      []store.Role
	}{
		{"GET", "/v1/org", nil, allRoles},
		{"GET", "/v1/members", nil, allRoles},
		{"GET", "/v1/invites", nil, allRoles},
		{"GET", "/v1/customers", nil, allRoles},
		{"GET", "/v1/customers/export.csv", nil, allRoles},
		{"GET", "/v1/plans", nil, allRoles},
		{"GET", "/v1/subscriptions", nil, allRoles},
		{"GET", "/v1/invoices", nil, allRoles},
		{"GET", "/v1/payments", nil, allRoles},
		{"GET", "/v1/api-keys", nil, allRoles},
		{"POST", "/v1/api-keys", map[string]string{"name": "CI"}, allRoles},
		{"DELETE", "/v1/api-keys/key_nope", nil, allRoles},

		{"POST", "/v1/customers", nil, nonViewers},
		{"PATCH", "/v1/customers/cus_nope", nil, nonViewers},
		{"DELETE", "/v1/customers/cus_nope", nil, nonViewers},

		{"POST", "/v1/plans", nil, billers},
		{"PATCH", "/v1/plans/plan_nope", nil, billers},

		{"POST", "/v1/subscriptions", nil, nonViewers},
		{"PATCH", "/v1/subscriptions/sub_nope", nil, nonViewers},
		{"POST", "/v1/subscriptions/sub_nope/cancel", nil, nonViewers},
		{"POST", "/v1/subscriptions/sub_nope/usage", nil, nonViewers},

		{"POST", "/v1/invoices", nil, billers},
		{"POST", "/v1/invoices/inv_nope/pay", nil, billers},
		{"POST", "/v1/invoices/inv_nope/void", nil, billers},
		{"GET", "/v1/reports/revenue", nil, billers},

		{"GET", "/v1/webhook-endpoints", nil, adminsOwner},
		{"POST", "/v1/webhook-endpoints", nil, adminsOwner},
		{"GET", "/v1/webhook-endpoints/whe_nope", nil, adminsOwner},
		{"GET", "/v1/webhook-endpoints/whe_nope/deliveries", nil, adminsOwner},
		{"GET", "/v1/events", nil, adminsOwner},
		{"GET", "/v1/events/evt_nope", nil, adminsOwner},

		{"PATCH", "/v1/org", nil, adminsOwner},
		{"POST", "/v1/invites", nil, adminsOwner},
		{"DELETE", "/v1/invites/inv_nope", nil, adminsOwner},
		{"PATCH", "/v1/members/usr_nope", nil, adminsOwner},
		{"DELETE", "/v1/members/usr_nope", nil, adminsOwner},
	}
	for _, c := range matrix {
		for _, role := range allRoles {
			r := e.Do(c.method, c.path, keys[role], c.body)
			label := c.method + " " + c.path + " as " + string(role)
			if slices.Contains(c.allowed, role) {
				if r.Code == http.StatusForbidden || r.Code == http.StatusUnauthorized {
					t.Errorf("%s: want past the role check, got %s", label, r)
				}
				continue
			}
			if r.Code != http.StatusForbidden || errorCode(t, r) != "forbidden" {
				t.Errorf("%s: want 403 forbidden, got %s", label, r)
			}
		}
	}
}

