// TestAPIKeyRules checks who may create, list and revoke API keys.
func TestAPIKeyRules(t *testing.T) {
	e := apitest.New(t)
	member, memberKey := e.AddMember(e.Acme, "member@acme.example", store.RoleMember)
	_, viewerKey := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
	var own store.APIKey
	e.MustDo(http.StatusCreated, "POST", "/v1/api-keys", viewerKey, map[string]string{"name": "Mine"}, &own)

	var viewerKeys struct{ Items []store.APIKey }
	e.MustDo(http.StatusOK, "GET", "/v1/api-keys", viewerKey, nil, &viewerKeys)
	if len(viewerKeys.Items) != 2 {
		t.Fatalf("a viewer lists %d keys, want their own 2 (their first and this one)", len(viewerKeys.Items))
	}
	for _, k := range viewerKeys.Items {
		if k.UserID == e.Acme.Owner.ID || k.UserID == member.ID {
			t.Fatalf("a viewer sees someone else's key: %+v", k)
		}
	}

	var all struct{ Items []store.APIKey }
	e.MustDo(http.StatusOK, "GET", "/v1/api-keys", e.Acme.Key, nil, &all)
	if len(all.Items) != 4 {
		t.Fatalf("an owner lists %d keys, want all 4", len(all.Items))
	}

	if r := e.Do("DELETE", "/v1/api-keys/"+e.Acme.Key[:0]+firstKeyOf(t, all.Items, member.ID), viewerKey, nil); r.Code != http.StatusForbidden {
		t.Fatalf("a viewer revokes another member's key: %s", r)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+own.ID, viewerKey, nil, nil)
	if r := e.Do("GET", "/v1/me", own.Token, nil); r.Code != http.StatusUnauthorized {
		t.Fatalf("a revoked key works: %s", r)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+firstKeyOf(t, all.Items, member.ID), e.Acme.Key, nil, nil)
	if r := e.Do("GET", "/v1/me", memberKey, nil); r.Code != http.StatusUnauthorized {
		t.Fatalf("an owner's revocation left the key working: %s", r)
	}
}

// errorCode is the "error" field of an answer.
func errorCode(t *testing.T, r *apitest.Response) string {
	t.Helper()
	body, _ := r.Map(t)["error"].(string)
	return strings.TrimSpace(body)
}

