// TestMemberRules checks who may change, invite, and remove owners, admins, billing users and members.
func TestMemberRules(t *testing.T) {
	e := apitest.New(t)
	ownerID := e.Acme.Owner.ID
	adminUser, adminKey := e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
	memberUser, memberKey := e.AddMember(e.Acme, "member@acme.example", store.RoleMember)
	viewerUser, viewerKey := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
	otherAdmin, _ := e.AddMember(e.Acme, "other-admin@acme.example", store.RoleAdmin)

	// Nobody changes their own role.
	if r := e.Do("PATCH", "/v1/members/"+ownerID, e.Acme.Key, map[string]string{"role": "member"}); r.Code != http.StatusForbidden {
		t.Fatalf("owner demotes themselves: %s", r)
	}
	if r := e.Do("PATCH", "/v1/members/"+adminUser.ID, adminKey, map[string]string{"role": "member"}); r.Code != http.StatusForbidden {
		t.Fatalf("admin demotes themselves: %s", r)
	}

	// Admins may not give or take away the owner or admin roles.
	for _, c := range []struct{ who, target, role string }{
		{adminKey, ownerID, "billing"},
		{adminKey, otherAdmin.ID, "billing"},
		{adminKey, memberUser.ID, "admin"},
		{adminKey, memberUser.ID, "owner"},
	} {
		if r := e.Do("PATCH", "/v1/members/"+c.target, c.who, map[string]string{"role": c.role}); r.Code != http.StatusForbidden {
			t.Fatalf("admin sets %s to %s: %s", c.target, c.role, r)
		}
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+memberUser.ID, adminKey, map[string]string{"role": "billing"}, nil)

	// Admins invite members, but only owners invite admins.
	if r := e.Do("POST", "/v1/invites", adminKey, map[string]string{"email": "new@people.example", "role": "admin"}); r.Code != http.StatusForbidden {
		t.Fatalf("admin invites an admin: %s", r)
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", adminKey, map[string]string{"email": "new@people.example", "role": "member"}, nil)
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "boss@people.example", "role": "admin"}, nil)

	// Removing others: admins remove members and billing users, but not owners or admins; members remove nobody.
	if r := e.Do("DELETE", "/v1/members/"+ownerID, adminKey, nil); r.Code != http.StatusForbidden {
		t.Fatalf("admin removes the owner: %s", r)
	}
	if r := e.Do("DELETE", "/v1/members/"+otherAdmin.ID, adminKey, nil); r.Code != http.StatusForbidden {
		t.Fatalf("admin removes an admin: %s", r)
	}
	if r := e.Do("DELETE", "/v1/members/"+adminUser.ID, memberKey, nil); r.Code != http.StatusForbidden {
		t.Fatalf("a billing user removes an admin: %s", r)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+memberUser.ID, adminKey, nil, nil)

	// Anyone may leave, and their key stops working.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+viewerUser.ID, viewerKey, nil, nil)
	if r := e.Do("GET", "/v1/me", viewerKey, nil); r.Code != http.StatusUnauthorized {
		t.Fatalf("a member who left still gets in: %s", r)
	}
}

// TestLastOwner checks that an organization always keeps an owner.
func TestLastOwner(t *testing.T) {
	e := apitest.New(t)
	ownerID := e.Acme.Owner.ID
	x, xKey := e.AddMember(e.Acme, "x@acme.example", store.RoleMember)
	if r := e.Do("DELETE", "/v1/members/"+ownerID, e.Acme.Key, nil); r.Code != http.StatusConflict || errorCode(t, r) != "last_owner" {
