	// Anyone may leave, and their key stops working.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+viewerUser.ID, viewerKey, nil, nil)
	if r := e.Do("GET", "/v1/me", viewerKey, nil); r.Code != http.StatusUnauthorized {
		t.Fatalf("a member who left still gets in: %s", r)
	}
}

// TestLastOwner checks that an organization always keeps an owner.
