84	// privileged reports whether a role is one only owners may give, take away or change: owner and admin.
85	func privileged(r store.Role) bool { return r == store.RoleOwner || r == store.RoleAdmin }
86	
87	func (s *Server) updateMember(w http.ResponseWriter, r *http.Request, p auth.Principal) {
88		target := r.PathValue("user_id")
89		if target == p.UserID {
90			writeError(w, http.StatusForbidden, "forbidden", "nobody may change their own role")
91			return
92		}
93		var in struct {
94			Role store.Role `json:"role"`
95		}
96		if !decode(w, r, &in) {
97			return
98		}
99		cur, ok := s.store.Member(p.OrgID, target)
100		if !ok {
101			s.storeError(w, store.ErrNotFound)
102			return
103		}
104		if (privileged(cur.Role) || privileged(in.Role)) && !auth.IsOwner(p.Role) {
105			writeError(w, http.StatusForbidden, "forbidden", "only owners change the owner and admin roles")
106			return
107		}
108		m, err := s.store.SetMemberRole(p.OrgID, target, in.Role)
109		if err != nil {
110			s.storeError(w, err)
111			return
112		}
113		writeJSON(w, http.StatusOK, s.memberView(m))
114	}
115	
116	// removeMember removes a member. Anyone may leave: a member may always remove themselves.
117	func (s *Server) removeMember(w http.ResponseWriter, r *http.Request, p auth.Principal) {
118		target := r.PathValue("user_id")
119		if target != p.UserID {
120			if !auth.CanManageTeam(p.Role) {
121				writeError(w, http.StatusForbidden, "forbidden", "only owners and admins remove other members")
122				return
123			}
124			cur, ok := s.store.Member(p.OrgID, target)
125			if !ok {
126				s.storeError(w, store.ErrNotFound)
127				return
128			}
129			if privileged(cur.Role) && !auth.IsOwner(p.Role) {
130				writeError(w, http.StatusForbidden, "forbidden", "only owners remove owners and admins")
131				return
132			}
133		}
134		if err := s.store.RemoveMember(p.OrgID, target); err != nil {
135			s.storeError(w, err)
136			return
137		}
138		w.WriteHeader(http.StatusNoContent)
139	}
