145	func (s *Server) createInvite(w http.ResponseWriter, r *http.Request, p auth.Principal) {
146		var in struct {
147			Email string     `json:"email"`
148			Role  store.Role `json:"role"`
149		}
150		if !decode(w, r, &in) {
151			return
152		}
153		if privileged(in.Role) && !auth.IsOwner(p.Role) {
154			writeError(w, http.StatusForbidden, "forbidden", "only owners invite owners and admins")
155			return
156		}
157		inv, err := s.store.CreateInvite(p.OrgID, in.Email, in.Role, p.UserID, s.clock.Now())
158		if err != nil {
159			s.storeError(w, err)
160			return
161		}
162		if err := s.sendInvite(r.Context(), inv); err != nil {
163			s.log.Error("send invite", "invite", inv.ID, "err", err)
164		}
165		writeJSON(w, http.StatusCreated, inv)
166	}
