168	// sendInvite emails the invite's link to the invited address.
169	func (s *Server) sendInvite(ctx context.Context, inv store.Invite) error {
170		o, _ := s.store.Org(inv.OrgID)
171		link := s.baseURL + "/invites/accept?token=" + url.QueryEscape(inv.Token)
172		return s.mail.Send(ctx, mail.Message{
173			To:      inv.Email,
174			Subject: fmt.Sprintf("You are invited to join %s on Tally", o.Name),
175			Body:    fmt.Sprintf("You have been invited to join %s on Tally as %s.\n\nAccept the invitation: %s\n", o.Name, inv.Role, link),
176		})
177	}
