179	func (s *Server) revokeInvite(w http.ResponseWriter, r *http.Request, p auth.Principal) {
180		if _, err := s.store.RevokeInvite(p.OrgID, r.PathValue("id"), s.clock.Now()); err != nil {
181			s.storeError(w, err)
182			return
183		}
184		w.WriteHeader(http.StatusNoContent)
185	}
186	
187	// acceptInvite needs no API key: the invite's token is the credential. It answers the new member and their first API key.
188	func (s *Server) acceptInvite(w http.ResponseWriter, r *http.Request) {
189		var in struct {
190			Token string `json:"token"`
191			Name  string `json:"name"`
192		}
193		if !decode(w, r, &in) {
194			return
195		}
196		u, m, k, err := s.store.AcceptInvite(in.Token, in.Name, s.clock.Now())
197		if err != nil {
198			if errors.Is(err, store.ErrNotFound) {
199				writeError(w, http.StatusNotFound, "invite_not_found", "no such invite")
200				return
201			}
202			s.storeError(w, err)
203			return
204		}
205		writeJSON(w, http.StatusCreated, map[string]any{"user": u, "member": s.memberView(m), "api_key": k})
206	}
207	
208	// listAPIKeys lists the organization's keys for owners and admins, and only the caller's own keys for everyone else.
209	func (s *Server) listAPIKeys(w http.ResponseWriter, r *http.Request, p auth.Principal) {
210		items := []store.APIKey{}
211		for _, k := range s.store.APIKeys(p.OrgID) {
212			if auth.CanAdminister(p.Role) || k.UserID == p.UserID {
213				items = append(items, k)
214			}
215		}
216		writeJSON(w, http.StatusOK, list{Items: items})
217	}
218	
219	func (s *Server) createAPIKey(w http.ResponseWriter, r *http.Request, p auth.Principal) {
220		var in struct {
221			Name string `json:"name"`
222		}
223		if !decode(w, r, &in) {
224			return
225		}
226		k, err := s.store.CreateAPIKey(p.OrgID, p.UserID, in.Name, s.clock.Now())
227		if err != nil {
228			s.storeError(w, err)
229			return
230		}
231		writeJSON(w, http.StatusCreated, k)
232	}
233	
234	// revokeAPIKey revokes a key. Anyone may revoke their own keys; only owners and admins may revoke anyone's.
235	func (s *Server) revokeAPIKey(w http.ResponseWriter, r *http.Request, p auth.Principal) {
236		k, ok := s.store.APIKey(p.OrgID, r.PathValue("id"))
237		if !ok {
238			s.storeError(w, store.ErrNotFound)
239			return
240		}
241		if k.UserID != p.UserID && !auth.CanAdminister(p.Role) {
242			writeError(w, http.StatusForbidden, "forbidden", "only owners and admins revoke other members' keys")
243			return
244		}
245		if _, err := s.store.RevokeAPIKey(p.OrgID, k.ID, s.clock.Now()); err != nil {
246			s.storeError(w, err)
247			return
248		}
249		w.WriteHeader(http.StatusNoContent)
250	}
