20	// TestRoleMatrix checks every endpoint's role table: a role that may not call an endpoint gets 403 "forbidden", and one
21	// that may gets past the role check (any answer but 401 or 403).
22	func TestRoleMatrix(t *testing.T) {
23		e := apitest.New(t)
24		keys := map[store.Role]string{store.RoleOwner: e.Acme.Key}
25		for _, role := range allRoles[1:] {
26			_, keys[role] = e.AddMember(e.Acme, string(role)+"@acme.example", role)
27		}
28		matrix := []struct {
29			method, path string
30			body         any
31			allowed      []store.Role
32		}{
33			{"GET", "/v1/org", nil, allRoles},
34			{"GET", "/v1/members", nil, allRoles},
35			{"GET", "/v1/invites", nil, allRoles},
36			{"GET", "/v1/customers", nil, allRoles},
37			{"GET", "/v1/customers/export.csv", nil, allRoles},
38			{"GET", "/v1/plans", nil, allRoles},
39			{"GET", "/v1/subscriptions", nil, allRoles},
40			{"GET", "/v1/invoices", nil, allRoles},
41			{"GET", "/v1/payments", nil, allRoles},
42			{"GET", "/v1/api-keys", nil, allRoles},
43			{"POST", "/v1/api-keys", map[string]string{"name": "CI"}, allRoles},
44			{"DELETE", "/v1/api-keys/key_nope", nil, allRoles},
45	
46			{"POST", "/v1/customers", nil, nonViewers},
47			{"PATCH", "/v1/customers/cus_nope", nil, nonViewers},
48			{"DELETE", "/v1/customers/cus_nope", nil, nonViewers},
49	
50			{"POST", "/v1/plans", nil, billers},
51			{"PATCH", "/v1/plans/plan_nope", nil, billers},
52	
53			{"POST", "/v1/subscriptions", nil, nonViewers},
54			{"PATCH", "/v1/subscriptions/sub_nope", nil, nonViewers},
55			{"POST", "/v1/subscriptions/sub_nope/cancel", nil, nonViewers},
56			{"POST", "/v1/subscriptions/sub_nope/usage", nil, nonViewers},
57	
58			{"POST", "/v1/invoices", nil, billers},
59			{"POST", "/v1/invoices/inv_nope/pay", nil, billers},
60			{"POST", "/v1/invoices/inv_nope/void", nil, billers},
61			{"GET", "/v1/reports/revenue", nil, billers},
62	
63			{"GET", "/v1/webhook-endpoints", nil, adminsOwner},
64			{"POST", "/v1/webhook-endpoints", nil, adminsOwner},
65			{"GET", "/v1/webhook-endpoints/whe_nope", nil, adminsOwner},
66			{"GET", "/v1/webhook-endpoints/whe_nope/deliveries", nil, adminsOwner},
67			{"GET", "/v1/events", nil, adminsOwner},
68			{"GET", "/v1/events/evt_nope", nil, adminsOwner},
69	
70			{"PATCH", "/v1/org", nil, adminsOwner},
71			{"POST", "/v1/invites", nil, adminsOwner},
72			{"DELETE", "/v1/invites/inv_nope", nil, adminsOwner},
73			{"PATCH", "/v1/members/usr_nope", nil, adminsOwner},
74			{"DELETE", "/v1/members/usr_nope", nil, adminsOwner},
75		}
76		for _, c := range matrix {
77			for _, role := range allRoles {
78				r := e.Do(c.method, c.path, keys[role], c.body)
79				label := c.method + " " + c.path + " as " + string(role)
80				if slices.Contains(c.allowed, role) {
81					if r.Code == http.StatusForbidden || r.Code == http.StatusUnauthorized {
82						t.Errorf("%s: want past the role check, got %s", label, r)
83					}
84					continue
