93	// TestRefusedRequestChangesNothing checks that a request refused by role leaves the data as it was.
94	func TestRefusedRequestChangesNothing(t *testing.T) {
95		e := apitest.New(t)
96		_, viewer := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
97		_, member := e.AddMember(e.Acme, "member@acme.example", store.RoleMember)
98		if r := e.Do("POST", "/v1/customers", viewer, map[string]string{"name": "X", "email": "x@example.com"}); r.Code != http.StatusForbidden {
