108			t.Fatalf("member renames a plan: %s", r)
109		}
110		var got store.Plan
111		e.MustDo(http.StatusOK, "GET", "/v1/plans/"+plan.ID, e.Acme.Key, nil, &got)
112		if got.Name != "Team" {
113			t.Fatalf("a refused rename changed the plan: %+v", got)
