133	// TestMemberRules checks who may change, invite, and remove owners, admins, billing users and members.
134	func TestMemberRules(t *testing.T) {
135		e := apitest.New(t)
136		ownerID := e.Acme.Owner.ID
137		adminUser, adminKey := e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
138		memberUser, memberKey := e.AddMember(e.Acme, "member@acme.example", store.RoleMember)
139		viewerUser, viewerKey := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
140		otherAdmin, _ := e.AddMember(e.Acme, "other-admin@acme.example", store.RoleAdmin)
141	
142		// Nobody changes their own role.
143		if r := e.Do("PATCH", "/v1/members/"+ownerID, e.Acme.Key, map[string]string{"role": "member"}); r.Code != http.StatusForbidden {
144			t.Fatalf("owner demotes themselves: %s", r)
145		}
146		if r := e.Do("PATCH", "/v1/members/"+adminUser.ID, adminKey, map[string]string{"role": "member"}); r.Code != http.StatusForbidden {
147			t.Fatalf("admin demotes themselves: %s", r)
148		}
149	
150		// Admins may not give or take away the owner or admin roles.
151		for _, c := range []struct{ who, target, role string }{
152			{adminKey, ownerID, "billing"},
153			{adminKey, otherAdmin.ID, "billing"},
154			{adminKey, memberUser.ID, "admin"},
155			{adminKey, memberUser.ID, "owner"},
156		} {
157			if r := e.Do("PATCH", "/v1/members/"+c.target, c.who, map[string]string{"role": c.role}); r.Code != http.StatusForbidden {
158				t.Fatalf("admin sets %s to %s: %s", c.target, c.role, r)
159			}
160		}
161		e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+memberUser.ID, adminKey, map[string]string{"role": "billing"}, nil)
162	
163		// Admins invite members, but only owners invite admins.
164		if r := e.Do("POST", "/v1/invites", adminKey, map[string]string{"email": "new@people.example", "role": "admin"}); r.Code != http.StatusForbidden {
165			t.Fatalf("admin invites an admin: %s", r)
166		}
167		e.MustDo(http.StatusCreated, "POST", "/v1/invites", adminKey, map[string]string{"email": "new@people.example", "role": "member"}, nil)
168		e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "boss@people.example", "role": "admin"}, nil)
169	
170		// Removing others: admins remove members and billing users, but not owners or admins; members remove nobody.
171		if r := e.Do("DELETE", "/v1/members/"+ownerID, adminKey, nil); r.Code != http.StatusForbidden {
172			t.Fatalf("admin removes the owner: %s", r)
173		}
174		if r := e.Do("DELETE", "/v1/members/"+otherAdmin.ID, adminKey, nil); r.Code != http.StatusForbidden {
175			t.Fatalf("admin removes an admin: %s", r)
176		}
177		if r := e.Do("DELETE", "/v1/members/"+adminUser.ID, memberKey, nil); r.Code != http.StatusForbidden {
178			t.Fatalf("a billing user removes an admin: %s", r)
179		}
180		e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+memberUser.ID, adminKey, nil, nil)
181	
182		// Anyone may leave, and their key stops working.
183		e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+viewerUser.ID, viewerKey, nil, nil)
184		if r := e.Do("GET", "/v1/me", viewerKey, nil); r.Code != http.StatusUnauthorized {
185			t.Fatalf("a member who left still gets in: %s", r)
186		}
187	}
