204	// TestAPIKeyRules checks who may create, list and revoke API keys.
205	func TestAPIKeyRules(t *testing.T) {
206		e := apitest.New(t)
207		member, memberKey := e.AddMember(e.Acme, "member@acme.example", store.RoleMember)
208		_, viewerKey := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
209		var own store.APIKey
210		e.MustDo(http.StatusCreated, "POST", "/v1/api-keys", viewerKey, map[string]string{"name": "Mine"}, &own)
211	
212		var viewerKeys struct{ Items []store.APIKey }
213		e.MustDo(http.StatusOK, "GET", "/v1/api-keys", viewerKey, nil, &viewerKeys)
214		if len(viewerKeys.Items) != 2 {
215			t.Fatalf("a viewer lists %d keys, want their 2 keys", len(viewerKeys.Items))
216		}
217		for _, k := range viewerKeys.Items {
218			if k.UserID != own.UserID {
219				t.Fatalf("a viewer sees someone else's key: %+v", k)
220			}
221		}
222	
223		var all struct{ Items []store.APIKey }
224		e.MustDo(http.StatusOK, "GET", "/v1/api-keys", e.Acme.Key, nil, &all)
225		if len(all.Items) != 4 {
226			t.Fatalf("an owner lists %d keys, want all 4", len(all.Items))
227		}
228	
229		memberKeyID := keyOf(t, all.Items, member.ID)
230		if r := e.Do("DELETE", "/v1/api-keys/"+memberKeyID, viewerKey, nil); r.Code != http.StatusForbidden {
231			t.Fatalf("a viewer revokes another member's key: %s", r)
232		}
233		e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+own.ID, viewerKey, nil, nil)
234		if r := e.Do("GET", "/v1/me", own.Token, nil); r.Code != http.StatusUnauthorized {
235			t.Fatalf("a revoked key works: %s", r)
236		}
237		e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+memberKeyID, e.Acme.Key, nil, nil)
238		if r := e.Do("GET", "/v1/me", memberKey, nil); r.Code != http.StatusUnauthorized {
239			t.Fatalf("an owner's revocation left the key working: %s", r)
240		}
241	}
