func (s *Server) updateMember(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	target := r.PathValue("user_id")
	var in struct {
		Role store.Role `json:"role"`
	}
	if !decode(w, r, &in) {
		return
	}
	if target == p.UserID {
		// The sole owner demoting themselves is a last-owner conflict, not a role refusal.
		if p.Role == store.RoleOwner && in.Role != store.RoleOwner && ownerCount(s.store.Members(p.OrgID)) == 1 {
			writeError(w, http.StatusConflict, "last_owner", "an organization keeps at least one owner")
			return
		}
		writeError(w, http.StatusForbidden, "forbidden", "nobody may change their own role")
		return
	}
	cur, ok := s.store.Member(p.OrgID, target)

